        [1219539] = "Unlocks your potential while inside Naxxramas.  Increasing your damage by ${$m1/100}.2% and your health by ${$m2/100}.2% for each Sanctified item equipped.  (Equipping more than $1223336s2 Sanctified items provides no additional benefit)",
        [1219540] = "Your Taunt ability never misses, and your chance to be Dodged or Parried is reduced by $s1%.",
        [1219543] = "Reduces the cooldown on your Shield Wall ability by ${$m1/-60000} min and reduces the cooldown on your Recklessness ability by ${$m1/-60000} min. Recklessness can now be used in any Stance and does not increase damage taken.",
        [1219544] = "When you take damage from an Undead enemy, the remaining duration of your active Last Stand is reset to $m1 sec.",
        [1219548] = "Unlocks your potential while inside Naxxramas.  Increasing your healing by ${$m1/100}.2% and your health by ${$m2/100}.2% for each Sanctified item equipped.  (Equipping more than $1223336s2 Sanctified items provides no additional benefit)",
        [1219577] = "Permanently enchant an Off-Hand to add $M1 to intellect.",
        [1219578] = "Permanently enchant an Off-Hand to add $M1 to spirit.",
        [1219579] = "Permanently enchant an Off-Hand to add $M1 to intellect and $M2 to spirit.",
        [1219580] = "Permanently enchant a 2H Weapon to add $M1 Spell Power.",
        [1219581] = "Permanently enchant a Shield to add $M1 to stamina.",
        [1219587] = "Permanently enchant a Cloak to add $M1 to agility.",
        [1219729] = "Take heavy Frost damage when this aura expires, shared among all nearby allies.\r\n",
        [1219732] = "Take heavy Frost damage when this aura expires, shared among all nearby allies.\r\n",
        [1219740] = "Permanently imbue your shoulders with the Soul of the Tactician:\r\n\r\nПісля зміни стійки витрати люті на вашу наступну бойову здібність зменшуються на $s1.",
        [1219741] = "Deals $s1 Shadow damage every $t1 sec. Slows movement speed by $s2%.",
        [1219742] = "Permanently imbue your shoulders with the Soul of the War Veteran:\r\n\r\nFor $457699d after leaving a stance, you can use abilities requiring that stance as if you were still in that stance.",
        [1219743] = "Permanently imbue your shoulders with the Soul of the Battle Forecaster:\r\n\r\nFor the first $457816d after activating a stance, you can gain an additional benefit:\r\n\r\nBattle Stance/Gladiator Stance: $457816s1% increased damage done.\r\n\r\nBerserker Stance: $457817s1% increased critical strike chance.\r\n\r\nDefensive Stance: $457814s1% reduced Physical damage taken.",
        [1219747] = "Permanently imbue your shoulders with the Soul of the Titan:\r\n\r\nЗдібності \"Героїчний удар\", \"Розтрощення\" та \"Здолання\" завдають на $s1% більше шкоди.",
        [1219749] = "Permanently imbue your shoulders with the Soul of the Deathbound:\r\n\r\nЗменшує час відновлення \"Жаги смерті\" на $s1%.",
        [1219751] = "Permanently imbue your shoulders with the Soul of the Sanguinist:\r\n\r\nВи завдаєте на $s1% більше шкоди, поки на когось з ворогів неподалік діють обидва ваші ефекти \"Розрив\" та \"Глибокі рани\".",
        [1219752] = "Permanently imbue your shoulders with the Soul of the Pristine Blocker:\r\n\r\nЗбільшує показник блокування вашого щита на $s1.",
        [1219753] = "Permanently imbue your shoulders with the Soul of the Savage:\r\n\r\nВи отримуєте додатково ${$457648m1/10} люті щоразу, коли отримуєте будь-яку шкоду чи завдаєте удару автоматичною атакою.",
        [1219754] = "Permanently imbue your shoulders with the Soul of Enmity:\r\n\r\nЗбільшує вашу загрозу в захисній стійці додатково на $s1% та збільшує вашу шкоду в стійці гладіатора на $s2%.",
        [1219755] = "Permanently imbue your shoulders with the Soul of the Deflective:\r\n\r\nВи отримуєте ${$468066m1/10} люті щоразу коли парируєте атаку чи вашу атаку парирують.",
        [1219756] = "Permanently imbue your shoulders with the Soul of the Revenger:\r\n\r\nRevenge also grants you Flurry, increasing your attack speed by $12970s1% for the next $12970n swings.",
        [1219757] = "Permanently imbue your shoulders with the Soul of the Incessant:\r\n\r\nWhen your target Parries an attack, you instantly Retaliate for $468071s2% weapon damage to that target. Retaliate cannot be Dodged, Blocked, or Parried, but can only occur once every $468071d per target.",
        [1219758] = "Permanently imbue your shoulders with the Soul of the Thunderbringer:\r\n\r\nЗменшує час відновлення \"Громового удару\" на $s1%.",
        [1219760] = "Permanently imbue your shoulders with the Soul of the Sentinel:\r\n\r\n\"Трощення щитом\" спричиняє на $s1% більше загрози, а його відновлення миттєво завершується, якщо його блокували, ухилилися або парирували.",
        [1219762] = "Permanently imbue your shoulders with the Soul of the Southpaw:\r\n\r\nЗменшує час відновлення здібності \"Трощення щитом\" на ${$m1/-1000} с.",
        [1219763] = "Permanently imbue your shoulders with the Soul of the Gladiator:\r\n\r\nЗменшує час відновлення здібності \"Кривава лють\" на ${$m1/-1000} с, поки ви перебуваєте в стійці гладіатора.",
        [1219764] = "Permanently imbue your shoulders with the Soul of the Aftershock:\r\n\r\nЗменшує час відновлення \"Ударної хвилі\" на $s1%.",
        [1219766] = "Permanently imbue your shoulders with the Soul of the Avoidant:\r\n\r\nFeint also grants Avoidance for $457331d, reducing all damage taken from area of effect attacks from non-players by $457331s1%.",
        [1219767] = "Permanently imbue your shoulders with the Soul of the Toxicologist:\r\n\r\nЗбільшує бонус критичної шкоди для ваших отрут на $s1%.",
        [1219768] = "Permanently imbue your shoulders with the Soul of the Executioner:\r\n\r\nВаші завершальні рухи з ймовірністю $b1% за кожен прийом в комбінації дозволять використати наступну здібність без витрат енергії.",
        [1219769] = "Permanently imbue your shoulders with the Soul of the Opportunist:\r\n\r\nЗдібності, що починають комбінацію прийомів, з ймовірністю $h% дозволять використати наступну здібність без витрат енергії.",
        [1219770] = "Permanently imbue your shoulders with the Soul of the Butcher:\r\n\r\nЗбільшує шкоду вашої зброї в правій руці на $s1% для здібностей, що продовжують комбінацію прийомів.",
        [1219771] = "Permanently imbue your shoulders with the Soul of the Phantom:\r\n\r\nЗменшує час відновлення \"Зникнення\" до ${$m3/60000} хв. Не поєднується з \"Невловимістю\".",
        [1219772] = "Permanently imbue your shoulders with the Soul of the Scoundrel:\r\n\r\nЗбільшує шкоду здібностей \"Скалічити\" та \"Удар шаблею\" на $s1%.",
        [1219773] = "Permanently imbue your shoulders with the Soul of the Thrill Seeker:\r\n\r\nЗменшує час відновлення \"Викиду адреналіну\" на ${$m1/-60000} хв.",
        [1219774] = "Permanently imbue your shoulders with the Soul of the Shiv Savant:\r\n\r\nЗбільшує ймовірність завдати критичного удару кинджалами на $s1%.",
        [1219775] = "Permanently imbue your shoulders with the Soul of the Stalker:\r\n\r\nЗбільшує шанс критичного удару Засідки на $s1%.",
        [1219776] = "Permanently imbue your shoulders with the Soul of the Efficient:\r\n\r\nВаші завершальні рухи витрачають на $s1% менше енергії.",
        [1219777] = "Permanently imbue your shoulders with the Soul of the Knife Juggler:\r\n\r\nWhile Just a Flesh Wound and Blade Dance are active, Crimson Tempest, Blunderbuss, and Fan of Knives cost $457351s1  less Energy and generate $457351s2% increased threat.",
        [1219778] = "Permanently imbue your shoulders with the Soul of the Shadow Master:\r\n\r\nVanish now reduces all Magic damage you take by $457437s1% for its duration, but it no longer grants Stealth or breaks movement impairing effects.",
        [1219779] = "Permanently imbue your shoulders with the Soul of the Equilibrist:\r\n\r\nYour finishing moves have a $b1% chance per combo point to make you take $457469s1% less Physical damage from the next melee attack that hits you within $457469d.",
        [1219781] = "Permanently imbue your shoulders with the Soul of the Black Belt:\r\n\r\n\"Удар за ударом\" також збільшує броню від предметів на $s1% за кожен ефект (але не більше ${$s1*5}%).",
        [1219784] = "Permanently imbue your shoulders with the Soul of the Bloodthirsty:\r\n\r\nПід час дії ефекту \"Удару лівицею\" ви зцілюєтесь на $s1% від заданої шкоди \"Підступним ударом\". Надлишкове зцілення захистить вас \"Бар'єром крові\", що поглинатиме шкоду в обсязі до $s2% від максимального запасу здоров'я.",
        [1219785] = "Permanently imbue your shoulders with the Soul of the Transfusionist:\r\n\r\n\"Витік життя\" відновлює на $s1% більше мани та спричиняє на $s2% менше загрози.",
        [1219786] = "Permanently imbue your shoulders with the Soul of the Refined:\r\n\r\nЗбільшує шанс завдання критичного удару всіма заклинаннями та атаками на $s1%.",
        [1219787] = "Permanently imbue your shoulders with the Soul of the Decimator:\r\n\r\nЙмовірність спрацювання таланту \"Сутінки\" збільшується на $s1%. \"Спалення\" з ймовірністю $h% спричиняє ефект \"Винищення\" незалежно від запасу здоров'я цілі.",
        [1219788] = "Permanently imbue your shoulders with the Soul of the Rotbringer:\r\n\r\nЗбільшує шкоду ваших заклять періодичної шкоди та вартового скверни на $s1%.",
        [1219789] = "Permanently imbue your shoulders with the Soul of the Malevolent:\r\n\r\nПеріодична шкода заклять \"Тіньове полум'я\", \"Нестабільна химородь\" та \"Прокляття агонії\", а також шкода вартового скверни з ймовірністю $h% спричинить ефект \"Тінетрансу\".",
        [1219790] = "Permanently imbue your shoulders with the Soul of the Shadowmancer:\r\n\r\n\"Тіньова стріла\" завдає на $s1% більше шкоди за кожен ваш ефект на цілі, максимум до $s2%.",
        [1219791] = "Permanently imbue your shoulders with the Soul of the Chaos Harbinger:\r\n\r\nЗменшує час відновлення \"Стріли Хаосу\" на $s1% та збільшує шкоду \"Стріли Хаосу\" та \"Тіньової стріли\" на $s2%. Окрім того, \"Стріла Хаосу\" тепер може спричинити ефект таланту \"Покращена тіньова стріла\" та збільшує максимальну кількість його ефектів на $s3 (не поєднується з додатковими ефектами від \"Тіньового полум'я\").",
        [1219792] = "Permanently imbue your shoulders with the Soul of the Arsonist:\r\n\r\nEach time you hit a target with Conflagrate, you gain $1214088s1% increased Fire damage for $1214088d, stacking up to $1214088u times.",
        [1219793] = "Permanently imbue your shoulders with the Soul of the Infernal Shepherd:\r\n\r\nЗбільшує силу атаки та шкоду заклять, які ваш прислужник отримує від ваших атрибутів, на $s1%.",
        [1219794] = "Permanently imbue your shoulders with the Soul of the Demonlord:\r\n\r\nПосилює ефект таланту \"Майстер-демонолог\" на $s1%.",
        [1219796] = "Permanently imbue your shoulders with the Soul of the Pained:\r\n\r\nЩоразу, коли ви отримуєте шкоду, ви і ваш вихованець отримуєте ману в обсязі, що дорівнює отриманій шкоді, але не більше $s1 мани за раз. Цей ефект може спрацьовувати лише раз на кілька секунд.",
        [1219797] = "Permanently imbue your shoulders with the Soul of the Flamewraith:\r\n\r\nYour Shadow Cleave hits have a $h% chance to grant you a Soul Shard, reset the cooldown on Soul Fire, and make your next Soul Fire within $457643d instant.",
        [1219798] = "Permanently imbue your shoulders with the Soul of the Fleshfeaster:\r\n\r\nWhile you are targeting an enemy within $468029r yards, Life Tap grants you mana at the expense of your target's health but deals $s1% reduced damage to them. Mana gained remains unchanged.",
        [1219799] = "Permanently imbue your shoulders with the Soul of the Abyssal:\r\n\r\nWhile Metamorphosis is active, your offensive abilities and Demon summons cost no Soul Shards. In addition, you heal for $468062s1% of your maximum health when you damage a target with Shadowburn.",
        [1219800] = "Permanently imbue your shoulders with the Soul of the Voidborne:\r\n\r\nНадлишкове самозцілення перетворюється на щит, який поглинає шкоду. Цей щит може поглинути до $s1% від вашого максимального запасу здоров'я, а також підсилюється від подальшого самозцілення.",
        [1219801] = "Permanently imbue your shoulders with the Soul of the Umbral Blade:\r\n\r\nReduces the cooldown on your Shadow Cleave by ${$m1/-1000}.1 sec.",
        [1219803] = "Permanently imbue your shoulders with the Soul of the Pain Spreader:\r\n\r\nFor $1214156d after using Shadowcleave, your Searing Pain strikes $1214156s1 additional target within melee range.",
        [1219804] = "Permanently imbue your shoulders with the Soul of the Misleader:\r\n\r\nYou generate $456339s1% more threat for $456339d after using Distracting Shot.",
        [1219805] = "Permanently imbue your shoulders with the Soul of the Preyseeker:\r\n\r\nWhile tracking a creature type, you deal $s1% increased damage to that creature type.",
        [1219806] = "Permanently imbue your shoulders with the Soul of the Sharpshooter:\r\n\r\nYour next Shot ability within $456382d after Aimed Shot deals $456382s1% more damage.",
        [1219807] = "Permanently imbue your shoulders with the Soul of the Hazard Harrier:\r\n\r\nВаш \"Прицільний постріл\" завдає на $s1% більше шкоди цілям, ураженим однією з ваших пасток.",
        [1219808] = "Permanently imbue your shoulders with the Soul of the Alternator:\r\n\r\nЗдібності-постріли, що завдають шкоди, завдають на $s1% більше шкоди, якщо попередній постріл було застосовано на іншу ціль.",
        [1219809] = "Permanently imbue your shoulders with the Soul of the Toxinologist:\r\n\r\nШкода \"Жала змії\" збільшується на $s1% від вашої сили атаки.",
        [1219810] = "Permanently imbue your shoulders with the Soul of the Bounty Hunter:\r\n\r\nЗбільшує шкоду \"Вбивчого пострілу\" проти цілей, що не перебувають під контролем гравців, на $s1%.",
        [1219811] = "Permanently imbue your shoulders with the Soul of the Trick Shooter:\r\n\r\nЧас відновлення \"Вбивчого пострілу\" зменшується на $s3%. Поки діє \"Швидка стрілянина\" з гравіюванням \"Швидкого вбивства\", \"Вбивчий постріл\" не має часу відновлення, а при використанні проти цілі, яка не контролюється гравцем, вистрілює $s4 додаткові \"Вбивчі постріли\", що завдають $s5% шкоди, з мінімальною дальністю дії.",
        [1219812] = "Permanently imbue your shoulders with the Soul of the Beast Tender:\r\n\r\nЗбільшує бонус до сили атаки вашого супутника від ваших характеристик на $s1%.",
        [1219813] = "Permanently imbue your shoulders with the Soul of the Hound Master:\r\n\r\nПрискорює відновлення концентрації вашого вихованця на $s1%.",
        [1219815] = "Permanently imbue your shoulders with the Soul of the Alpha Tamer:\r\n\r\nПрискорює відновлення концентрації ваших вихованців на $s1%.",
        [1219816] = "Permanently imbue your shoulders with the Soul of the Huntsman:\r\n\r\nYour Mongoose Bite also reduces its target's chance to Dodge by $456393s1% and increases your chance to hit by $458403s1% for $456393d.",
        [1219818] = "Permanently imbue your shoulders with the Soul of the Retaliator:\r\n\r\nMongoose Bite also activates for $5302d whenever your target Parries or Blocks or when your melee attack misses.",
        [1219819] = "Permanently imbue your shoulders with the Soul of Echoes:\r\n\r\nRaptor Strike increases the damage done by your next other melee ability (excluding Wing Clip) within $467331d by $467331s1%.",
        [1219820] = "Permanently imbue your shoulders with the Soul of the Lethal Lasher:\r\n\r\nЗбільшує шкоду зброї в правій руці для здібностей \"Удар раптора\" та \"Удар виверни\" на $s1%.",
        [1219821] = "Permanently imbue your shoulders with the Soul of the Kineticist:\r\n\r\nВаша періодична шкода з ймовірністю $h% завершить відновлення здібності-удару з найдовшим поточним часом відновленння.",
        [1219822] = "Permanently imbue your shoulders with the Soul of the Strategist:\r\n\r\nЗбільшує періодичну шкоду \"Удару виверни\" на $s1% та збільшує максимальний запас концентрації вашого супутника на $s2.",
        [1219823] = "Permanently imbue your shoulders with the Soul of the Deadly Striker:\r\n\r\nЗбільшує первинну шкоду \"Укусу мангусти\" та всіх ударів на $s1%.",
        [1219824] = "Permanently imbue your shoulders with the Soul of the Hastened Healer:\r\n\r\n-$/1000;S1 sec to the casting time of Flash Heal and -$/1000;S2 sec to the casting time of Greater Heal.",
        [1219825] = "Permanently imbue your shoulders with the Soul of the Refined:\r\n\r\nЗбільшує шанс завдання критичного удару всіма заклинаннями та атаками на $s1%.",
        [1219826] = "Permanently imbue your shoulders with the Soul of the Celebrant:\r\n\r\nЗбільшує ймовірність критичного ефекту \"Молитви зцілення\" та \"Кола зцілення\" на $s1%.",
        [1219827] = "Permanently imbue your shoulders with the Soul of the Faithful:\r\n\r\nДозволяє $s1% відновлення мани продовжувати діяти під час застосування заклять.",
        [1219828] = "Permanently imbue your shoulders with the Soul of the Serendipitous:\r\n\r\nВаше періодичне зцілення з ймовірністю $h% дозволить миттєво вимовити наступне закляття з тривалістю вимови менше 10 с.",
        [1219829] = "Permanently imbue your shoulders with the Soul of the Resonant:\r\n\r\nCircle of Healing and Penance also place a heal over time effect on their targets that heals for $s1% as much over $467588d.",
        [1219830] = "Permanently imbue your shoulders with the Soul of the Devotee:\r\n\r\nВаша \"Молитва загоєння\" отримує ще $s1 заряди.",
        [1219831] = "Permanently imbue your shoulders with the Soul of the Archbishop:\r\n\r\n\"Коло зцілення\" відновлює найбільш пораненому учаснику групи цілі на $s1% більше здоров'я.",
        [1219832] = "Permanently imbue your shoulders with the Soul of the Penitent:\r\n\r\nЗменшує час відновлення \"Сповіді\" на ${$m1/-1000} с.",
        [1219833] = "Permanently imbue your shoulders with the Soul of the Soul Warder:\r\n\r\nЗбільшує обсяг поглинання закляття \"Слово сили: Щит\" на $s1%.",
        [1219835] = "Permanently imbue your shoulders with the Soul of the Mind Breaker:\r\n\r\nMind Blast critical strikes reduce the duration of your next Mind Flay by $456549s1% while increasing its total damage by $456549s3%.",
        [1219836] = "Permanently imbue your shoulders with the Soul of the Deathdealer:\r\n\r\nЗменшує час відновлення закляття \"Слово тіні: Смерть\" на ${$m1/-1000} с.",
        [1219837] = "Permanently imbue your shoulders with the Soul of the Spirit Font:\r\n\r\nYour Shadow Word: Pain has a ${$m1/10}.1% chance per talent point in Spirit Tap to trigger your Spirit Tap talent when it deals damage, or a $s2% chance per talent point when a target dies with your Shadow Word: Pain active. Inner Focus also has a $s2% chance per talent point to trigger Spirit Tap.",
        [1219838] = "Permanently imbue your shoulders with the Soul of the Zealot:\r\n\r\nWhile Spirit Tap is active, you deal $467632s1% more Shadow damage.",
        [1219840] = "Permanently imbue your shoulders with the Soul of the Contemnor:\r\n\r\n\"Пронизування розуму\" тепер вимовляється миттево, завдає на $s2% більше шкоди і його можна вимовити під час промовляння інших заклять.",
        [1219842] = "Permanently imbue your shoulders with the Soul of the Reverberant:\r\n\r\nВаші \"Темпоральні маяки\" тривають на $s1% довше.",
        [1219843] = "Permanently imbue your shoulders with the Soul of the Chronohealer:\r\n\r\nЗбільшує все ваше хрономантичне зцілення на $s1%.",
        [1219844] = "Permanently imbue your shoulders with the Soul of Temporal Longing:\r\n\r\nЩоразу, коли ви зцілюєте ціль \"Регенерацією\", час відновлення \"Повернення у часі\" скорочується на $s1 с.",
        [1219845] = "Permanently imbue your shoulders with the Soul of the Precognitive:\r\n\r\nВаші \"Арканічні снаряди\" відновлюють вам $s1% від базових витрат мани на них щоразу, коли завдають шкоди.",
        [1219846] = "Permanently imbue your shoulders with the Soul of the Arcanist:\r\n\r\n\"Арканічний спалах\" має на $s1% більшу ймовірність викликати ефект \"Обстрілу снарядами\", а \"Обстріл снарядами\" впливає на \"Регенерацію\" так само, як і на \"Арканічні снаряди\".",
        [1219847] = "Permanently imbue your shoulders with the Soul of the Eternal Caretaker:\r\n\r\nВаші \"Темпоральні маяки\", спричинені \"Масовою регенерацією\" тепер тривають $m1 с.",
        [1219848] = "Permanently imbue your shoulders with the Soul of the Spellbider:\r\n\r\n\"Арканічний спалах\" додатково збільшує шкоду на $s1% за кожен ефект.",
        [1219849] = "Permanently imbue your shoulders with the Soul of the Wardshaper:\r\n\r\nYour Mana Shield, Fire Ward, and Frost Ward absorb $s1% more damage and also place a Temporal Beacon on the target for $400735d.",
        [1219850] = "Permanently imbue your shoulders with the Soul of Winter's Grasp:\r\n\r\nЗбільшує ймовірність спрацювання руни \"Крижані пальці\" на $s1%.",
        [1219851] = "Permanently imbue your shoulders with the Soul of the Cryomancer:\r\n\r\nЗбільшує шкоду заклять \"Крижана стріла\" та \"Чарокрижана стріла\" на $s1%.",
        [1219853] = "Permanently imbue your shoulders with the Soul of the Elementalist:\r\n\r\nYou gain $456400s1% increased damage for $456400d each time you cast a spell from a different school of magic.",
        [1219854] = "Permanently imbue your shoulders with the Soul of the Magical Armorer:\r\n\r\n\"Магівський обладунок\" збільшує відновлення мани під час вимови заклять ще на $s1%. \"Розплавлений обладунок\" збільшує шкоду і зцілення ваших заклять на $s2. \"Льодяний обладунок\" збільшує ймовірність спрацювання ефекту \"Крижаних пальців\" на $s3%.",
        [1219855] = "Permanently imbue your shoulders with the Soul of the Kindler:\r\n\r\nЗменшує загрозу ваших вогняних заклять на $s1%.",
        [1219856] = "Permanently imbue your shoulders with the Soul of Fiery Convergence:\r\n\r\n\"Вогняна брила\" завдає на $s1% більше шкоди цілі, що перебуває під ефектом періодиної шкоди вашої \"Вогняної кулі\".",
        [1219857] = "Permanently imbue your shoulders with the Soul of the Perpetual Blaze:\r\n\r\nЗбільшує загальну шкоду ефекту \"Вогняної кулі\" на $s1% від первинної шкоди.",
        [1219858] = "Permanently imbue your shoulders with the Soul of the Pyromaniac:\r\n\r\nYour Fire Blast now also causes your next Fire spell to gain $1213317s1% increased critical strike chance for $1213317d.",
        [1219859] = "Permanently imbue your shoulders with the Soul of the Igniter:\r\n\r\nЗбільшує шкоду від таланту \"Займання\" на $s1%.",
        [1219860] = "Permanently imbue your shoulders with the Soul of the Torcher:\r\n\r\nЗакляття \"Вогняна куля\", \"Стріла крижаного полум'я\" та \"Стріла руйнівного полум'я\" завдають на $s1% більше шкоди за кожен ваш вогняний ефект на цілі, максимум до $s2%.",
        [1219861] = "Permanently imbue your shoulders with the Soul of the Pristine Blocker:\r\n\r\nЗбільшує показник блокування вашого щита на $s1.",
        [1219862] = "Permanently imbue your shoulders with the Soul of the Lightwarden:\r\n\r\nHeal for $456540s1 when you Block. Can only heal once every few seconds.",
        [1219863] = "Permanently imbue your shoulders with the Soul of the Radiant Defender:\r\n\r\nСвященний щит більше не має зарядів і не спадає від блокувань. Крім того, його шкода збільшується на $s2% від вашого показника блоку щитом.",
        [1219864] = "Permanently imbue your shoulders with the Soul of the Shieldbearer:\r\n\r\nЗбільшує бонус до ймовірності блокування від \"Священного щита\" на $s1%.",
        [1219865] = "Permanently imbue your shoulders with the Soul of the Bastion:\r\n\r\nYou take $467534s1% reduced damage while Holy Shield is active.",
        [1219866] = "Permanently imbue your shoulders with the Soul of the Reckoner:\r\n\r\nТалант \"Воздаяння\" з ймовірністю $s1% за ранг спрацьовує, коли ви блокуєте.",
        [1219867] = "Permanently imbue your shoulders with the Soul of the Ironclad:\r\n\r\nYour Blessing of Sanctuary also grants $1213408s1% increase to all stats when cast on yourself.",
        [1219868] = "Permanently imbue your shoulders with the Soul of the Guardian:\r\n\r\nПісля застосування \"Щита праведника\" ваше наступне \"Священне світло\" вимовляється миттєво. При застосуванні закляття на себе, воно відновить $s1% витраченої мани, і на нього не впливатиме ефект \"Під захистом Світла\".",
        [1219869] = "Permanently imbue your shoulders with the Soul of the Peacekeeper:\r\n\r\nЗбільшує ймовірність спрацювання \"Присуду світла\" та \"Присуду мудрості\" для ваших союзників до $s1%.",
        [1219870] = "Permanently imbue your shoulders with the Soul of the Refined:\r\n\r\nЗбільшує шанс завдання критичного удару всіма заклинаннями та атаками на $s1%.",
        [1219871] = "Permanently imbue your shoulders with the Soul of the Exemplar:\r\n\r\nWhenever your Flash of Light, Holy Light, or Beacon of Light heals a target to full health, you also heal all members of their party for $s1 health.",
        [1219872] = "Permanently imbue your shoulders with the Soul of the Inquisitor:\r\n\r\nЗбільшує ймовірність критичного ефекту \"Священного шоку\" на $s1%.",
        [1219873] = "Permanently imbue your shoulders with the Soul of the Sovereign:\r\n\r\nЗбільшує шкоду вашого \"Освячення\" на $s1%.",
        [1219874] = "Permanently imbue your shoulders with the Soul of the Dominus:\r\n\r\nЯкщо на вас не діє \"Маяк світла\", ви зцілюєте ціль вашого \"Маяка світла\" на $s1% від вашої шкоди, завданої закляттями \"Освячення\", \"Екзорцизм\", \"Священний шок\", \"Священний гнів\" та \"Молот гніву\".",
        [1219875] = "Permanently imbue your shoulders with the Soul of the Vindicator:\r\n\r\nЗменшує час відновлення \"Божественного світла\" на $s1%.",
        [1219876] = "Permanently imbue your shoulders with the Soul of the Altruist:\r\n\r\nКоли \"Маяк Світла\" зцілює ціль, він також зцілює найближчу дружню поранену ціль на $s1% свого ефекту.",
        [1219878] = "Permanently imbue your shoulders with the Soul of the Sealbearer:\r\n\r\nВаші печатки наказу, праведності та мучеництва, а також \"Сонячне сяйво\" завдають на $s2% менше шкоди, але продовжують діяти протягом $s1 с після накладання іншої печатки або до накладання третьої. \"Присуд\" тепер може викликати спрацювання кількох печаток.",
        [1219879] = "Permanently imbue your shoulders with the Soul of the Justicar:\r\n\r\nВаші \"Присуди\" завдають на $s1% більше шкоди та не поглинають ефекти печаток з цілі. Також \"Присуди\" тепер можуть викликати спрацювання кількох печаток.",
        [1219880] = "Permanently imbue your shoulders with the Soul of the Judicator:\r\n\r\nЗменшує час відновлення \"Присудів\" на ${$m1/-1000} с, але зменшує їхню шкоду на $s2%.",
        [1219881] = "Permanently imbue your shoulders with the Soul of the Ascendant:\r\n\r\nYour Judgement grants $467530s1% increased Holy damage for $467530d, stacking up to $467530u times.",
        [1219882] = "Permanently imbue your shoulders with the Soul of the Retributor:\r\n\r\nЗбільшує шкоду \"Удару лицаря\" на $s1%.",
        [1219883] = "Permanently imbue your shoulders with the Soul of the Excommunicator:\r\n\r\nYour basic attacks with two-handed melee weapons increase the damage of your next Exorcism cast within $1217927d by $1217927s1%.  Stacking up to $s1 times.",
        [1219884] = "Permanently imbue your shoulders with the Soul of the Lightbringer:\r\n\r\nЗбільшує шкоду \"Священного шоку\" на $s1%.",
        [1219885] = "Permanently imbue your shoulders with the Soul of the Exile:\r\n\r\nЗменшує час відновлення \"Екзорцизму\" на ${$m1/-1000} с та збільшує його шкоду на $s2%.",
        [1219887] = "Permanently imbue your shoulders with the Soul of the Windwalker:\r\n\r\nIncreases your attack speed by $16280s1% for your next 3 swings after you parry, dodge, or block.",
        [1219889] = "Permanently imbue your shoulders with the Soul of the Totemic Protector:\r\n\r\nВаш \"Тотем кам'яної шкіри\" також зменшує отриману фізичну шкоду на $s1%, а ваш \"Тотем стіни вітру\" також зменшує отриману магічну шкоду на $s1%",
        [1219890] = "Permanently imbue your shoulders with the Soul of the Shock-Absorber:\r\n\r\nYour Flame Shock also grants $467891s1% increased chance to Block for $467891d or until you Block an attack.",
        [1219891] = "Permanently imbue your shoulders with the Soul of the Spiritual Bulwark:\r\n\r\nEach time you Block, your Block amount is increased by $s1% of your Spell Damage for $467910d, stacking up to $467910u times.",
        [1219892] = "Permanently imbue your shoulders with the Soul of the Maelstrombringer:\r\n\r\nЩоразу, коли ви блокуєте атаку, ви з ймовірністю $h% отримаєте ефект \"Зброї Водоверті\".",
        [1219893] = "Permanently imbue your shoulders with the Soul of the Lavawalker:\r\n\r\nDamaging a target with Stormstrike, Lava Burst, or Molten Blast also reduces all damage you take by $1213934s1% for $1213934d.",
        [1219894] = "Permanently imbue your shoulders with the Soul of the True Alpha:\r\n\r\nWhen your Spirit of the Alpha is cast on yourself, it also increases your health by $1213939s1%, your threat generated by $1213939s2%, and all damage you deal by $1213939s3%.",
        [1219895] = "Permanently imbue your shoulders with the Soul of the Totemkeeper:\r\n\r\nРадіус дії тотемів, що діють на союзників, збільшується до ${$m1+20} м.",
        [1219896] = "Permanently imbue your shoulders with the Soul of the Ancestors:\r\n\r\nПісля вимови \"Хвилі зцілення\", \"Малої хвилі зцілення\" та \"Бистрини\" ви з ймовірністю $h% відновите ману в обсязі $s1% від базової вартості закляття.",
        [1219897] = "Permanently imbue your shoulders with the Soul of the Spiritweaver:\r\n\r\nВаша \"Хвиля зцілення\" також перестрибує на цілі неподалік, з кожним стрибком зцілюючи на $s2% менше. Максимум до ${$m1-1} стрибків.",
        [1219898] = "Permanently imbue your shoulders with the Soul of the Waterwalker:\r\n\r\nВаші неперіодичні критичні ефекти шкоди та зцілення з ймовірністю $h% активують ефект \"Водяного щита\", але не поглинають його та не починають його відновлення.",
        [1219899] = "Permanently imbue your shoulders with the Soul of the Stormtender:\r\n\r\n\"Ланцюгова блискавка\" також зцілює останню ціль вашого \"Щита землі\" на $s1% від завданої шкоди.",
        [1219900] = "Permanently imbue your shoulders with the Soul of the Elemental Seer:\r\n\r\nЗбільшує ефективність \"Ланцюгового зцілення\" та шкоду \"Ланцюгової блискавки\" на $s1%.",
        [1219901] = "Permanently imbue your shoulders with the Soul of the Vitalist:\r\n\r\nВаша \"Бистрина\" також збільшує ефективність \"Ланцюгового зцілення\" на $s1%.",
        [1219902] = "Permanently imbue your shoulders with the Soul of the Spirithealer:\r\n\r\nReduces the cast time of Chain Heal by ${$m1/-1000}.1 sec.",
        [1219903] = "Permanently imbue your shoulders with the Soul of the Refined:\r\n\r\nЗбільшує шанс завдання критичного удару всіма заклинаннями та атаками на $s1%.",
        [1219904] = "Permanently imbue your shoulders with the Soul of the Chieftain:\r\n\r\nТалант \"Шквал\" збільшує вашу швидкість атаки ще на $s1%.",
        [1219905] = "Permanently imbue your shoulders with the Soul of the Furycharged:\r\n\r\nШанс спрацювання \"Електростатики\" збільшується на $m1% (на ${$m1/2}% якщо тримаєте по зброї в кожній руці).",
        [1219906] = "Permanently imbue your shoulders with the Soul of the Stormbreaker:\r\n\r\nЗбільшує шкоду зброї в правій руці для \"Штормового удару\" на $s1%.",
        [1219907] = "Permanently imbue your shoulders with the Soul of the Tempest:\r\n\r\nПоки ви мажєте активну руну \"Електростатика\", ваш \"Блискавковий щит\" отримує заряд щоразу, коли ви вражаєте ціль \"Блискавкою\" чи \"Ланцюговою блискавкою\", накопичуючи до ${$432134m1+3} зарядів, а його шкода може бути критичною.",
        [1219908] = "Permanently imbue your shoulders with the Soul of the Seismic Smasher:\r\n\r\nЗбільшує шкоду \"Штормового удару\" та \"Удару лавою\" на $s1%. Збільшує шкоду на $s2% при використанні дворучної зброї.",
        [1219909] = "Permanently imbue your shoulders with the Soul of the Flamebringer:\r\n\r\nYour Stormstrike, Lava Lash and Lava Burst critical strikes cause your target to burn for $s1% of the damage done over $1213915d.",
        [1219910] = "Permanently imbue your shoulders with the Soul of the Volcano:\r\n\r\nYour Lightning Bolt critical strikes have a $h% chance to reset the cooldown on Lava Burst and Chain Lightning and make the next Lava Burst or Chain Lightning within $415105d instant.\r\n",
        [1219911] = "Permanently imbue your shoulders with the Soul of the Raging Flame:\r\n\r\nLava Burst now also refreshes the duration of Flame Shock on your target back to $29228d.\r\n",
        [1219912] = "Permanently imbue your shoulders with the Soul of the Elemental Master:\r\n\r\nКритичні удари ваших заклять з ймовірністю $h% спричинять ефект таланту \"Стихійна зосередженість\".",
        [1219913] = "Permanently imbue your shoulders with the Soul of the Tribesman:\r\n\r\nЕфект \"Вірний бета\" вашої здібності \"Дух альфа-вовка\" тепер збільшує шкоду від вогню, криги та природи на $s1%.",
        [1219914] = "Permanently imbue your shoulders with the Soul of the Spirit Guide:\r\n\r\nПоки діє ефект \"Ясномови\" ви завдаєте на $s2% більше нефізичної шкоди.",
        [1219915] = "Permanently imbue your shoulders with the Soul of the Elder:\r\n\r\nЗ ймовірністю $s1% ви уникнете затримки вимови заклять \"Блискавка\", \"Ланцюгова блискавка\" та \"Виверження лави\" при отриманні шкоди, а шанс спрацювання таланту \"Стихійна зосередженість\" збільшується на $s2%.",
        [1219916] = "Permanently imbue your shoulders with the Soul of the Elements:\r\n\r\nЗбільшує додаткову шкоду від критичних ударів заклять вогню, криги та природи на $s1%.",
        [1219918] = "Permanently imbue your shoulders with the Soul of the Ancestral Warden:\r\n\r\nЗбільшує шанс блокувати атаки щитом на $s1%.",
        [1219919] = "Permanently imbue your shoulders with the Soul of the Corrupt:\r\n\r\nЗбільшує ймовірність спрацювання руни \"Сплеск сили\" на $s1%.",
        [1219921] = "Permanently imbue your shoulders with the Soul of the Ferocious:\r\n\r\n\"Несамовитість\" має на ${$m1/-1000} секунд зменшений час відновлення і більше не зменшує вашу броню.",
        [1219922] = "Permanently imbue your shoulders with the Soul of the Shifter:\r\n\r\nУ подобах ведмедя та жахливого ведмедя ви спричиняєте на $s1% більше загрози, а \"Зіщулювання\" тепер прибирає всю вашу загрозу цілі але має на ${$m2/1000} с більший час відновлення.",
        [1219923] = "Permanently imbue your shoulders with the Soul of the Territorial:\r\n\r\nSwipe(Bear) also causes your Maul to hit $467217s1 additional target for the next $467217d.",
        [1219924] = "Permanently imbue your shoulders with the Soul of the Beast:\r\n\r\nЗдібності \"Нівечення (ведмідь)\", \"Розмах (ведмідь)\", \"Терзання\" та \"Розірвати\" мають на $s1% більшу ймовірність завдання критичного удару цілям під ефектом здібності \"Розірвати\".",
        [1219926] = "Permanently imbue your shoulders with the Soul of the Furious:\r\n\r\nEach time you Dodge while in Dire Bear Form, you gain $1213190s1% increased damage on your next Mangle or Swipe, stacking up to $1213190u times.",
        [1219927] = "Permanently imbue your shoulders with the Soul of the Mangler:\r\n\r\nReduces the cooldown on Mangle (Bear) by ${$m1/-1000}.1 sec.",
        [1219929] = "Permanently imbue your shoulders with the Soul of the Nurturer:\r\n\r\nПісля вимови \"Цілющого дотику\" або \"Підживлення\" ви з ймовірністю $h% відновите ману в обсязі $s1% від базової вартості закляття.",
        [1219930] = "Permanently imbue your shoulders with the Soul of the Tranquil:\r\n\r\nЗменшує час відновлення \"Спокою\" на $s1% та збільшує його зцілення на $s2%.",
        [1219931] = "Permanently imbue your shoulders with the Soul of the Dreamwalker:\r\n\r\nYour healing spell critical strikes trigger the Dreamstate effect, granting you $408261s1% of your mana regeneration while casting for $408261d. ",
        [1219932] = "Permanently imbue your shoulders with the Soul of the Grove Tender:\r\n\r\nYour non-periodic spell critical strikes reduce the casting time of your next Healing Touch, Regrowth, or Nourish spell by ${$467204m1/-1000}.1 sec.",
        [1219933] = "Permanently imbue your shoulders with the Soul of the Feathered Sage:\r\n\r\nIncreases healing from Wild Growth by $s1%. In addition, Wild Growth can now be used in Moonkin Form, and its healing is increased by an additional $467206s2% in that form.",
        [1219934] = "Permanently imbue your shoulders with the Soul of the Benevolent Seer:\r\n\r\nЗменшує час відновлення заклять \"Переродження\" та \"Осяяння\" на $s1%.",
        [1219935] = "Permanently imbue your shoulders with the Soul of the Lifeweaver:\r\n\r\nКритичні ефекти \"Цілющого дотику\", \"Розростання\" та \"Підживлення\" миттєво відновлюють цілі ще $s1% від первинного ефекту зцілення.",
        [1219936] = "Permanently imbue your shoulders with the Soul of the Illuminator:\r\n\r\nYour Faerie Fire (Feral) also increases the chance for all attacks to hit that target by $455868s1% for $455868d.",
        [1219938] = "Permanently imbue your shoulders with the Soul of the Ripper:\r\n\r\nYour Rip and Ferocious Bite have a $455903s1% chance per combo point spent to refresh the duration of Savage Roar back to its initial value.",
        [1219939] = "Permanently imbue your shoulders with the Soul of the Claw:\r\n\r\nЗбільшує тривалість ефекту \"Роздирання\" на ${$m2/1000} с та збільшує його періодичну шкоду на $m1%.",
        [1219940] = "Permanently imbue your shoulders with the Soul of the Prideful:\r\n\r\nYour critical strike chance is increased by $467209s1% while Tiger's Fury is active.",
        [1219941] = "Permanently imbue your shoulders with the Soul of the Barbaric:\r\n\r\nЗдібності \"Шматування\", \"Безжалісний укус\" та \"Нівечення (кіт)\" завдають на $s1% більше шкоди за кожен ваш ефект кровотечі, максимум до $s2%.",
        [1219942] = "Permanently imbue your shoulders with the Soul of the Frenetic:\r\n\r\n\"Шматування\" більше не має вимоги до позиціонування, але завдає на $s1% більше шкоди, якщо ви знаходитесь за спиною цілі.",
        [1219943] = "Permanently imbue your shoulders with the Soul of the Exsanguinator:\r\n\r\nYour Mangle, Shred, and Ferocious Bite critical strikes cause your target to Bleed for $s1% of the damage done over the next $1213176d sec.",
